.ds-demo .ds-due-count{
  display: inline-block;
  min-width: 29px;
  background: #f0eadf;
  border: 1px solid #ded9ce;
  color: #596174;
  border-radius: 5px;
  padding: 4px 8px;
  font-size: 0.77rem;
  font-variant-numeric: tabular-nums;
}


















.ds-demo .ds-library-tree{
  padding: 0;
  margin: 0;
  list-style: none;
}

.ds-demo .ds-library-row{
  display: flex;
  align-items: stretch;
  padding-left: calc(var(--folder-depth) * 24px);
  border-bottom: 1px solid var(--line, #ded9ce);
}
.ds-demo .ds-folder-toggle{
  flex: 0 0 42px;
  width: 42px;
}
.ds-demo .ds-folder-toggle{
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted, #596174);
  border-radius: 4px;
}
.ds-demo .ds-folder-toggle:hover{
  background: var(--soft, #f0eadf);
}
.ds-demo .ds-folder-toggle:disabled{
  opacity: 1;
}

.ds-demo .ds-library-item{
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
  text-align: left;
  gap: 15px;
  padding: 18px 12px;
  border-radius: 4px;
}
.ds-demo .ds-library-item:hover{
  background: #f7f2e8;
}
.ds-demo .ds-library-symbol{
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 42px;
  flex-shrink: 0;
  color: var(--action, #1f2a44);
  background: var(--soft, #f0eadf);
  border-radius: 6px;
}
.ds-demo .ds-folder-symbol{
  background: transparent;
}
.ds-demo .ds-library-name{
  flex: 1;
  min-width: 0;
}
.ds-demo .ds-library-name strong{
  display: block;
  font-size: 0.93rem;
  font-weight: 560;
  overflow-wrap: anywhere;
}
.ds-demo .ds-library-name small{
  display: block;
  margin-top: 5px;
  font-size: 0.75rem;
  color: var(--muted, #596174);
}
.ds-demo .ds-library-item > .ds-due-count{
  flex-shrink: 0;
  min-width: 34px;
  text-align: center;
}
.ds-demo .ds-library-open{
  flex-shrink: 0;
  color: var(--muted, #596174);
}





